      +`<div class="field"><label class="field-label" for="hf-kinds">Facility kinds</label><input id="hf-kinds" data-hf-list="kinds" maxlength="200" value="${esc((p.kinds||[]).join(', '))}" placeholder="hospital, clinic"></div>`
